  // points espacés de `pas` le long de la ligne brisée pts (chaîne de perles, corps de dragon) ; f(x, y, i) → pièce
  const surLigne = (pts, pas, f) => {
    const out = []; let reste = 0, k = 0;
    for (let i = 0; i + 1 < pts.length; i++) {
      const [x0, y0] = pts[i], [x1, y1] = pts[i + 1], L = Math.hypot(x1 - x0, y1 - y0); let d = reste;
      for (; d <= L; d += pas) out.push(f(r1(x0 + (x1 - x0) * d / L), r1(y0 + (y1 - y0) * d / L), k++));
      reste = d - L;
    }
    return out;
  };
  const parabole = (cx, y0, demi, haut, n = 24) => Array.from({ length: n + 1 }, (_, i) => { const t = -1 + 2 * i / n; return [cx + demi * t, y0 + haut * (1 - t * t)]; });
  const hexa = (cx, cy, r, rot = 0) => Array.from({ length: 6 }, (_, i) => [r1(cx + r * Math.cos((rot + i * 60) * RAD)), r1(cy + r * Math.sin((rot + i * 60) * RAD))]);
